INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_LDS','Latter-day Saint / Restoration Era',1820,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_GIVENS_WRESTLING','secondary scholarship','Terryl L. Givens, Wrestling the Angel: The Foundations of Mormon Thought — Cosmos, God, Humanity (Oxford University Press, 2015)','Standard scholarly synthesis of LDS theology: premortal existence, Godhead, Heavenly Father/Mother, exaltation/theosis, council in heaven, three degrees of glory.'),
 ('SRC_PEARL_GREAT_PRICE','primary text','The Pearl of Great Price (LDS canonical scripture: Book of Moses, Book of Abraham, Joseph Smith—History, Articles of Faith)','Primary source for Kolob, the council in heaven, the premortal council, Michael=Adam, the creation account, and Moroni''s appearances (Joseph Smith—History).'),
 ('SRC_LDS_DC','primary text','Doctrine and Covenants (LDS canonical scripture, 1835–)','Primary source for the three degrees of glory (Celestial/Terrestrial/Telestial, D&C 76 and 131), exaltation, and the identification of Michael as Adam (D&C 27, 107, 116).')
INSERT INTO _e VALUES
 ('ENT_LDS_GODHEAD','The Godhead (LDS)','Divine collective','Godhead/principle','Latter-day Saint','supreme divinity; tritheistic unity of purpose','B','Canonical (Articles of Faith 1; D&C 130:22): three distinct personages — Father, Son, Holy Ghost — one in purpose, not one substance. Cohort hub.'),
 ('ENT_LDS_ELOHIM','Heavenly Father (Elohim)','Supreme deity','Creator deity','Latter-day Saint','exalted embodied Father of spirits; supreme God','B','Attested in LDS scripture and temple usage; an exalted, embodied, anthropomorphic God who was once a man (Givens, Wrestling the Angel). Distinct LDS conception, not the classical Trinity''s Father.'),
 ('ENT_LDS_HEAVENLY_MOTHER','Heavenly Mother','Mother goddess','Mother goddess','Latter-day Saint','divine feminine; mother of spirits; consort of Heavenly Father','B','Officially affirmed (Gospel Topics essay ''Mother in Heaven''; Eliza R. Snow hymn ''O My Father''); divine consort and co-parent of premortal spirits (Givens, Wrestling the Angel).'),
 ('ENT_LDS_JEHOVAH_CHRIST','Jehovah / Jesus Christ (LDS)','Messiah/incarnate Logos','Savior figure','Latter-day Saint','premortal Jehovah, creator under the Father, incarnate Redeemer','B','LDS framing identifies the premortal Jehovah of the Old Testament with Jesus Christ, the Firstborn spirit and Son who created the worlds under the Father (Givens; Bible Dictionary, ''Jehovah''). Cross-links to existing ENT_JESUS_CHRIST as the LDS reception.'),
 ('ENT_LDS_HOLY_GHOST','Holy Ghost (LDS)','Divine person','Divine person','Latter-day Saint','third member of the Godhead; personage of spirit; witness/revelator','B','Canonical (D&C 130:22): a personage of spirit without a body of flesh, distinct from the Father and Son. LDS reception of the Christian Holy Spirit.'),
 ('ENT_LDS_PREMORTAL_SPIRITS','Premortal Spirit Existence (Pre-existence)','Cosmological category','Cosmological realm','Latter-day Saint','premortal life of spirits as God''s children before birth','B','Doctrine of premortal existence: all humans lived as spirit children of Heavenly Parents before mortal birth (Givens; Book of Abraham 3; D&C 93:29).'),
 ('ENT_LDS_COUNCIL_HEAVEN','Council in Heaven','Cosmological process','Mythic process/category','Latter-day Saint','premortal divine council on the plan of salvation','B','Premortal council where the Father presented the plan of salvation; Jesus and Lucifer offered competing roles, leading to the War in Heaven (Book of Abraham 3; Book of Moses 4; Givens).'),
 ('ENT_LDS_MICHAEL_ADAM','Michael / Adam (LDS)','Archangel/exalted being','First human / Patriarch','Latter-day Saint','archangel Michael who became Adam, the first man and Ancient of Days','B','Canonical identification (D&C 27:11; 107:54; 116): the archangel Michael is Adam, the first man, the ''Ancient of Days'' who presides over his posterity. Cross-links to existing Adam and Michael anchors as LDS reception.'),
 ('ENT_LDS_MORONI','Moroni (Angel)','Revealer/angelic figure','Revealer','Latter-day Saint','resurrected Nephite prophet; angelic revealer of the golden plates','B','Joseph Smith—History (Pearl of Great Price): last Nephite prophet-historian, resurrected as the angel who revealed and delivered the golden plates from which the Book of Mormon was translated.'),
 ('ENT_LDS_LUCIFER','Lucifer / Perdition (LDS)','Adversarial being','Adversarial being','Latter-day Saint','premortal Son of the Morning who rebelled and became Satan','B','Book of Moses 4 and D&C 76:25–27: a spirit son of God in the premortal council who sought to supplant the plan and was cast out, becoming the devil and the sons of perdition.'),
 ('ENT_LDS_KOLOB','Kolob','Stellar god','Celestial sphere','Latter-day Saint','the star/realm nearest to the throne of God','B','Book of Abraham 3 and Facsimile 2: the great star/governing body nearest to where God resides, governing in time and order; a realm in LDS cosmology.'),
 ('ENT_LDS_DEGREES_GLORY','Three Degrees of Glory','Soteriological realm/category','Afterlife realm','Latter-day Saint','the tripartite kingdoms of eternal reward','B','D&C 76: the three postmortal kingdoms (Celestial, Terrestrial, Telestial) into which resurrected souls are assigned by glory; parent category of the three kingdoms.'),
 ('ENT_LDS_CELESTIAL_KINGDOM','Celestial Kingdom','Afterlife realm','Afterlife realm','Latter-day Saint','highest degree of glory; dwelling of God and the exalted','B','D&C 76:50–70, 131: the highest kingdom, where God and Christ dwell and where the exalted may attain godhood; likened to the glory of the sun.'),
 ('ENT_LDS_TERRESTRIAL_KINGDOM','Terrestrial Kingdom','Afterlife realm','Afterlife realm','Latter-day Saint','middle degree of glory','B','D&C 76:71–80: the middle kingdom for honorable people who did not receive the fulness of the gospel; likened to the glory of the moon.'),
 ('ENT_LDS_TELESTIAL_KINGDOM','Telestial Kingdom','Afterlife realm','Afterlife realm','Latter-day Saint','lowest degree of glory','B','D&C 76:81–90: the lowest of the three kingdoms of glory; likened to the glory of the stars.'),
 ('ENT_LDS_EXALTATION','Exaltation (Theosis)','Soteriological process/category','Soteriological process/category','Latter-day Saint','becoming gods; eternal increase in the Celestial Kingdom','B','Doctrine of exaltation/divinization: faithful Saints may attain godhood and eternal family increase (Lorenzo Snow couplet; D&C 132; Givens, Wrestling the Angel). LDS form of theosis.'),
 ('ENT_LDS_PLAN_SALVATION','Plan of Salvation','Doctrine','Soteriological/devotional category','Latter-day Saint','the divine plan of premortal, mortal, and postmortal progression','B','The overarching LDS doctrinal framework presented at the Council in Heaven, encompassing premortal life, mortality, and the degrees of glory (Givens; Book of Abraham 3).');
