INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_LDS_ELOHIM','member_of','ENT_LDS_GODHEAD','high','Heavenly Father (Elohim) is the first member of the LDS Godhead (Articles of Faith 1).'),
 ('ENT_LDS_JEHOVAH_CHRIST','member_of','ENT_LDS_GODHEAD','high','Jehovah/Jesus Christ is the second member of the LDS Godhead (D&C 130:22).'),
 ('ENT_LDS_HOLY_GHOST','member_of','ENT_LDS_GODHEAD','high','The Holy Ghost is the third member of the LDS Godhead (D&C 130:22).'),
 ('ENT_LDS_HEAVENLY_MOTHER','consort_of','ENT_LDS_ELOHIM','high','Heavenly Mother is the divine consort of Heavenly Father and co-parent of premortal spirits (Givens; Gospel Topics ''Mother in Heaven'').'),
 ('ENT_LDS_JEHOVAH_CHRIST','child_of','ENT_LDS_ELOHIM','high','Jesus Christ is the Firstborn spirit child and literal Son of Heavenly Father in LDS theology (Givens).'),
 ('ENT_LDS_JEHOVAH_CHRIST','child_of','ENT_LDS_HEAVENLY_MOTHER','medium','As all premortal spirits are children of Heavenly Parents, Jesus is the firstborn spirit child of the Heavenly Mother as well (Givens).'),
 ('ENT_LDS_LUCIFER','child_of','ENT_LDS_ELOHIM','high','Lucifer is a premortal spirit son of God who rebelled in the Council in Heaven (Book of Moses 4:1–4).'),
 ('ENT_LDS_LUCIFER','opposes','ENT_LDS_JEHOVAH_CHRIST','high','Lucifer offered a rival plan opposing Christ''s at the Council in Heaven and was cast out (Book of Moses 4; D&C 76:25–28).'),
 ('ENT_LDS_JEHOVAH_CHRIST','participates_in_creation','ENT_LDS_KOLOB','medium','Under the Father, the premortal Jehovah/Christ is the creator of the worlds; Kolob governs in the LDS cosmological order created in this framework (Book of Abraham 3–4).'),
 ('ENT_LDS_COUNCIL_HEAVEN','presided_over_by','ENT_LDS_ELOHIM','high','Heavenly Father presided over the premortal Council in Heaven where the plan of salvation was presented (Book of Abraham 3; Givens).'),
 ('ENT_LDS_PREMORTAL_SPIRITS','child_of','ENT_LDS_ELOHIM','high','All premortal spirits are the spirit children of Heavenly Father (Book of Abraham 3; D&C 93:29; Givens).'),
 ('ENT_LDS_PREMORTAL_SPIRITS','child_of','ENT_LDS_HEAVENLY_MOTHER','high','Premortal spirits are co-parented by the Heavenly Mother (Givens; hymn ''O My Father'').'),
 ('ENT_LDS_PREMORTAL_SPIRITS','participates_in_creation','ENT_LDS_COUNCIL_HEAVEN','medium','The premortal spirits, including the ''noble and great ones,'' participated in the Council in Heaven (Book of Abraham 3:22–28).'),
 ('ENT_LDS_COUNCIL_HEAVEN','member_of','ENT_LDS_PLAN_SALVATION','medium','The Council in Heaven is the premortal episode within the overarching Plan of Salvation where that plan was presented (Givens).'),
 ('ENT_LDS_PREMORTAL_SPIRITS','member_of','ENT_LDS_PLAN_SALVATION','medium','Premortal spirit existence is the first stage of the LDS Plan of Salvation (Givens).'),
 ('ENT_LDS_DEGREES_GLORY','member_of','ENT_LDS_PLAN_SALVATION','medium','The three degrees of glory are the postmortal reward stage of the Plan of Salvation (D&C 76; Givens).'),
 ('ENT_LDS_CELESTIAL_KINGDOM','member_of','ENT_LDS_DEGREES_GLORY','high','The Celestial Kingdom is the highest of the three degrees of glory (D&C 76).'),
 ('ENT_LDS_TERRESTRIAL_KINGDOM','member_of','ENT_LDS_DEGREES_GLORY','high','The Terrestrial Kingdom is the middle of the three degrees of glory (D&C 76).'),
 ('ENT_LDS_TELESTIAL_KINGDOM','member_of','ENT_LDS_DEGREES_GLORY','high','The Telestial Kingdom is the lowest of the three degrees of glory (D&C 76).'),
 ('ENT_LDS_ELOHIM','dwells_in','ENT_LDS_CELESTIAL_KINGDOM','high','God dwells in the Celestial Kingdom, the highest degree of glory (D&C 76:62, 92).'),
 ('ENT_LDS_KOLOB','dwelling_of','ENT_LDS_ELOHIM','medium','Kolob is the great governing star ''nearest unto the throne of God,'' i.e. the celestial body nearest God''s dwelling (Book of Abraham 3:2–3, 9; Facsimile 2). [QA FIX: replaced invalid ''member_of Godhead'' edge — Kolob is a realm, not a personage of the Godhead.]'),
 ('ENT_LDS_EXALTATION','member_of','ENT_LDS_PLAN_SALVATION','medium','Exaltation (godhood) is the culminating goal of the Plan of Salvation within the Celestial Kingdom (D&C 132; Givens).'),
 ('ENT_LDS_EXALTATION','belongs_to_realm','ENT_LDS_CELESTIAL_KINGDOM','high','Exaltation is attained only in the highest degree of the Celestial Kingdom (D&C 131:1–4).'),
 ('ENT_LDS_MICHAEL_ADAM','member_of','ENT_LDS_PREMORTAL_SPIRITS','medium','Michael/Adam was among the noble and great premortal spirits before becoming the first man (D&C 107:54; Book of Abraham 3).'),
 ('ENT_LDS_MORONI','member_of','ENT_LDS_PREMORTAL_SPIRITS','medium','Moroni, as a resurrected human prophet, was (like all humans) a premortal spirit child of Heavenly Parents before mortal birth (Givens; Book of Abraham 3). [QA FIX: replaced stretched ''reveals Godhead'' edge — Moroni revealed the golden plates, not ''the Godhead'' as an object.]'),
 ('ENT_LDS_ELOHIM','reception_of','ENT_CHR_GOD_FATHER','high','The LDS Heavenly Father (Elohim) is the Restorationist reception/reconception of the Christian God the Father — embodied and exalted rather than the classical Trinity (Givens).'),
 ('ENT_LDS_JEHOVAH_CHRIST','reception_of','ENT_JESUS_CHRIST','high','The LDS Jehovah/Jesus Christ is the Restorationist reception of the Christian Jesus, identifying him with the premortal Old Testament Jehovah (Bible Dictionary; Givens).'),
 ('ENT_LDS_HOLY_GHOST','reception_of','ENT_CHR_HOLY_SPIRIT','high','The LDS Holy Ghost is the Restorationist reception of the Christian Holy Spirit, reconceived as a distinct personage of spirit (D&C 130:22).'),
 ('ENT_LDS_MICHAEL_ADAM','reception_of','ENT_ISR_ADAM','high','LDS doctrine receives the biblical Adam and identifies him with the archangel Michael (D&C 27:11; 107:54).'),
 ('ENT_LDS_MICHAEL_ADAM','equated_with','ENT_SAINT_MICHAEL_CHR','high','LDS scripture explicitly equates the archangel Michael with Adam (D&C 116; 107:54); links to the Christian archangel Michael as the equated figure.');
